INSERT INTO products (product_id, name, brand, category, sport, price, description) VALUES
(1, 'Cloudrunner 3', 'Swiftfoot', 'Running Shoes', 'Running', 129.99, 'Lightweight neutral road running shoe with a soft foam midsole for daily training and long easy miles. Breathable mesh upper; not waterproof.'),
(2, 'Tempo Racer', 'Swiftfoot', 'Running Shoes', 'Running', 159.99, 'Carbon-plated racing shoe for 5K to marathon race day. Very light and bouncy with a firm, fast ride and minimal cushioning.'),
(3, 'StormGuard Runner', 'Nimbus Athletics', 'Running Shoes', 'Running', 139.99, 'Waterproof road running shoe with a sealed membrane and grippy rubber outsole for running in the rain on wet streets. Keeps feet dry through puddles.'),
(4, 'Stability Plus', 'Nimbus Athletics', 'Running Shoes', 'Running', 119.99, 'Supportive stability running shoe for overpronation and flat feet, with a firm medial post and a wide toe box.'),
(5, 'Comfort Walk', 'Nimbus Athletics', 'Walking Shoes', 'Walking', 89.99, 'Cushioned walking shoe for all-day comfort, standing at work, and travel. Slip-resistant sole.'),
(6, 'Ridge GTX', 'Trailborn', 'Trail Shoes', 'Trail Running', 149.99, 'Waterproof trail running shoe with deep lugs for mud, rain, and wet rocky trails. A rock plate protects from sharp stones.'),
(7, 'Desert Glide', 'Trailborn', 'Trail Shoes', 'Trail Running', 124.99, 'Breathable, quick-drying trail shoe for hot, dry desert and dusty summer trails. Sand-blocking mesh upper.'),
(8, 'Summit Hiker Mid', 'Trailborn', 'Hiking Boots', 'Hiking', 179.99, 'Mid-cut waterproof hiking boot with ankle support for multi-day backpacking with heavy loads. Sticky rubber sole.'),
(9, 'Downpour Shell', 'Peakline', 'Rain Jackets', 'Hiking', 189.99, 'Fully waterproof, breathable three-layer rain jacket with taped seams and an adjustable hood. Packs into its own pocket; built for hiking in storms.'),
(10, 'Featherlight Wind Jacket', 'Peakline', 'Running Jackets', 'Running', 79.99, 'Ultralight windbreaker for running on cold, windy days. Water-resistant but not for heavy rain. Reflective details for night runs.'),
(11, 'Insulated Puffer', 'Peakline', 'Winter Jackets', 'Hiking', 219.99, 'Warm down puffer jacket for freezing temperatures, winter camping, and ski trips. Lightweight and compressible.'),
(12, 'Hi-Vis Running Vest', 'Tidewater', 'Running Accessories', 'Running', 34.99, 'Bright reflective safety vest with a clip-on LED light for running or cycling at night and early in the morning near traffic.'),
(13, 'Pro Tour 300', 'Courtline', 'Tennis Rackets', 'Tennis', 219.99, 'Control-oriented tennis racket for advanced players: 300 g, 98 sq in head, for flat, powerful strokes.'),
(14, 'Ace Lite', 'Courtline', 'Tennis Rackets', 'Tennis', 99.99, 'Lightweight, forgiving tennis racket with a large sweet spot for beginners and juniors learning the game.'),
(15, 'Clay Court Shoe', 'Courtline', 'Tennis Shoes', 'Tennis', 109.99, 'Tennis shoe with a herringbone outsole for clay courts and quick side-to-side movement. Durable toe guard.'),
(16, 'Championship Balls 4-Pack', 'Courtline', 'Tennis Balls', 'Tennis', 7.99, 'Pressurized extra-duty tennis balls for hard courts.'),
(17, 'Aero Road Helmet', 'VeloForge', 'Cycling Helmets', 'Cycling', 149.99, 'Aerodynamic road cycling helmet with rotational impact protection and strong ventilation for fast rides.'),
(18, 'Commuter Helmet with Light', 'VeloForge', 'Cycling Helmets', 'Cycling', 69.99, 'Urban bike helmet with a built-in rear LED light for commuting in city traffic at night.'),
(19, 'Padded Bib Shorts', 'VeloForge', 'Cycling Apparel', 'Cycling', 89.99, 'Cycling bib shorts with a dense chamois pad for long hours in the saddle.'),
(20, 'Rain Cape', 'VeloForge', 'Cycling Apparel', 'Cycling', 59.99, 'Waterproof cycling rain cape that covers your hands and handlebars when commuting by bike in the rain.'),
(21, 'Mini Pump', 'VeloForge', 'Cycling Accessories', 'Cycling', 24.99, 'Compact hand pump for road and mountain bike tires that fits in a jersey pocket.'),
(22, 'Grip Pro Yoga Mat', 'Zenmat', 'Yoga Mats', 'Yoga', 89.99, 'Non-slip natural rubber yoga mat for hot yoga and sweaty practice. 5 mm thick, with extra grip when wet.'),
(23, 'Travel Fold Mat', 'Zenmat', 'Yoga Mats', 'Yoga', 39.99, 'Thin 1.5 mm foldable yoga mat that fits in a suitcase, for practicing yoga while traveling.'),
(24, 'Cork Yoga Block 2-Pack', 'Zenmat', 'Yoga Accessories', 'Yoga', 24.99, 'Eco-friendly cork blocks that give support in poses and help with flexibility work.'),
(25, 'Seamless Leggings', 'Zenmat', 'Yoga Apparel', 'Yoga', 64.99, 'High-waisted, squat-proof leggings with four-way stretch for yoga, pilates, and the gym.'),
(26, 'Adjustable Dumbbells', 'Ridgeback Gear', 'Strength Training', 'Fitness', 299.99, 'Pair of adjustable dumbbells from 2 to 24 kg with a quick-change dial, saving space in a home gym.'),
(27, 'Resistance Bands Set', 'Ridgeback Gear', 'Strength Training', 'Fitness', 29.99, 'Five latex resistance bands with handles for home workouts, physical therapy, and travel.'),
(28, 'Speed Jump Rope', 'Ridgeback Gear', 'Cardio', 'Fitness', 19.99, 'Ball-bearing speed rope for cardio, boxing training, and double-unders.'),
(29, 'Foam Roller', 'Ridgeback Gear', 'Recovery', 'Fitness', 34.99, 'High-density foam roller for muscle recovery and self-massage after running or lifting.'),
(30, 'Anti-Fog Goggles', 'AquaStride', 'Swimming Goggles', 'Swimming', 24.99, 'Anti-fog, UV-protected swim goggles with a wide field of view for pool laps and open water.'),
(31, 'Performance Swimsuit', 'AquaStride', 'Swimwear', 'Swimming', 74.99, 'Chlorine-resistant competitive swimsuit for training and racing in the pool.'),
(32, 'Open Water Wetsuit', 'AquaStride', 'Wetsuits', 'Triathlon', 349.99, 'Neoprene triathlon wetsuit for open-water swimming in cold lakes and the sea; buoyant, with flexible shoulders.'),
(33, 'Court Elite', 'Nimbus Athletics', 'Basketball Shoes', 'Basketball', 139.99, 'High-top basketball shoe with ankle support and responsive cushioning for jumping and quick cuts on indoor courts.'),
(34, 'Indoor Basketball', 'Ridgeback Gear', 'Basketballs', 'Basketball', 49.99, 'Official size 7 composite leather basketball with great grip for indoor games.'),
(35, 'Firm Ground Cleats', 'Swiftfoot', 'Soccer Cleats', 'Soccer', 119.99, 'Soccer cleats with molded studs for firm natural-grass pitches and a light upper for a clean touch on the ball.'),
(36, 'Match Soccer Ball', 'Ridgeback Gear', 'Soccer Balls', 'Soccer', 39.99, 'Size 5 thermally bonded soccer ball for training and matches.'),
(37, 'Trail Daypack 22L', 'Peakline', 'Backpacks', 'Hiking', 99.99, '22-liter hiking daypack with a rain cover, hydration sleeve, and ventilated back panel.'),
(38, 'Insulated Bottle 1L', 'Tidewater', 'Hydration', 'Hiking', 32.99, 'Double-wall steel bottle that keeps drinks cold for 24 hours on hikes and at the gym.'),
(39, 'Running Hydration Vest', 'Tidewater', 'Running Accessories', 'Running', 119.99, 'Lightweight running vest with two soft flasks for long trail runs and ultramarathons.'),
(40, 'Merino Hiking Socks 3-Pack', 'Peakline', 'Socks', 'Hiking', 44.99, 'Merino wool socks that stay warm when wet, resist odor, and prevent blisters on long hikes.'),
(41, 'Running Socks 3-Pack', 'Swiftfoot', 'Socks', 'Running', 19.99, 'Thin, moisture-wicking running socks with arch support and a no-show cut.'),
(42, 'GPS Running Watch', 'Nimbus Athletics', 'Electronics', 'Running', 249.99, 'GPS running watch with heart rate, pace, and training plans, and a 14-day battery.');
